def camel_match(queries, pattern):
    def matches(query):
        j = 0
        for ch in query:
            if j < len(pattern) and ch == pattern[j]:
                j += 1
            elif ch.isupper():
                return False
        return j == len(pattern)

    return [matches(q) for q in queries]

